"""Fixed P2P wire fixtures; encryption bytes checked previously with OpenSSL."""
import unittest
from uv_reference import FrameStream, encode_p2p_frame, decode_p2p_frame_body


class P2PWireTests(unittest.TestCase):
    def test_encrypted_wire_fixture_fragmentation_and_multiple_frames(self):
        iv = bytes(range(16))
        # Retained OpenSSL AES256-CBC fixture, not generated by the code under test.
        ciphertext = bytes.fromhex(
            "f4d7b86aaba934643deb80baa08305cde"
            "6723d81f617d17f43aa6ad11b12d6e5")
        expected = b"\x30\x00\x00\x00" + iv + ciphertext
        payload = "login:12345678".encode("utf-16le")
        self.assertEqual(encode_p2p_frame(payload, unicode_bytes=True,
                                         encryption_password="fixture-P2P!", iv=iv),
                         expected)
        stream = FrameStream()
        bodies = []
        for octet in expected + expected:
            bodies.extend(stream.feed(bytes((octet,))))
        self.assertEqual(len(bodies), 2)
        for body in bodies:
            self.assertEqual(decode_p2p_frame_body(
                body, encryption_password="fixture-P2P!"), (payload, True))
        self.assertEqual(stream.buffer, b"")

    def test_unencrypted_binary_payload_and_noncanonical_receive_flag(self):
        payload = b"\xff\x00\x80binary"
        expected = b"\x0a\x00\x00\x00\x00" + payload
        self.assertEqual(encode_p2p_frame(payload, unicode_bytes=False,
                                         encryption_password=None), expected)
        self.assertEqual(decode_p2p_frame_body(expected[4:], encryption_password=None),
                         (payload, False))
        # Original receive CIL tests >0, not equality with one.
        self.assertEqual(decode_p2p_frame_body(b"\xffX", encryption_password=None),
                         (b"X", True))
        self.assertEqual(decode_p2p_frame_body(b"\x01", encryption_password=None),
                         (b"", True))
        with self.assertRaises(ValueError):
            decode_p2p_frame_body(b"", encryption_password=None)


if __name__ == "__main__":
    unittest.main()
